html:
{%- set _lh = frappe.db.get_value("Letter Head", {"is_default": 1, "disabled": 0}, ["content", "footer"], as_dict=True) -%}{#zimam-lh#}
{%- if _lh and _lh.content and "<!--zimam-->" in _lh.content -%}<div class="zimam-lh-head">{{ _lh.content }}</div>{%- endif -%}
<div class="zimam-page" style="position:relative; min-height:212mm;">
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set org_name = company.company_name -%}
{%- if org_name|lower == "zimam" -%}{%- set org_name = (frappe.db.get_value("Company", {"is_group": 1}, "company_name") or org_name) -%}{%- endif -%}
{%- macro acct(v) -%}{{ (v or "").replace(" - " + (company.abbr or ""), "") }}{%- endmacro -%}
{%- set currency = doc.paid_to_account_currency or company.default_currency -%}
{%- set cur_words = {"OMR": ("ريال عماني", "بيسة"), "SAR": ("ريال سعودي", "هللة"), "AED": ("درهم إماراتي", "فلس"), "KWD": ("دينار كويتي", "فلس"), "QAR": ("ريال قطري", "درهم"), "BHD": ("دينار بحريني", "فلس"), "USD": ("دولار أمريكي", "سنت")} -%}
{%- macro words(amount) -%}
{%- set w = frappe.utils.money_in_words(amount, currency) -%}
{%- if currency in cur_words -%}{{ w.replace(currency, cur_words[currency][0]).replace("Baisa", cur_words[currency][1]).replace("Halala", cur_words[currency][1]).replace("Fils", cur_words[currency][1]).replace("Dirham", cur_words[currency][1]).replace("Cent", cur_words[currency][1]).replace("فقط.", "فقط") }}{%- else -%}{{ w }}{%- endif -%}
{%- endmacro -%}
{%- macro money(v) -%}<span dir="ltr" style="unicode-bidi:isolate;">{{ frappe.utils.fmt_money(v, currency=currency) }}</span>{%- endmacro -%}
{%- macro user(u) -%}{{ frappe.db.get_value("User", u, "full_name") if u else "" }}{%- endmacro -%}
{%- set td = 'style="border:1px solid #bbb; padding:4px 8px;"' -%}
{%- set lbl = 'style="border:1px solid #bbb; padding:4px 8px; width:22%; background:#faf7f2;"' -%}
{%- set fund_name = frappe.db.get_value("Treasury Fund", doc.zimam_fund, "fund_name") if doc.zimam_fund else "" -%}
{%- set state = "مسودة — غير معتمد" if doc.docstatus == 0 else ("ملغى" if doc.docstatus == 2 else "معتمد") -%}
<div dir="rtl" lang="ar" style="direction:rtl; text-align:right; font-family:'Sakkal Majalla','Noto Naskh Arabic','Amiri',serif; font-size:13.5pt; line-height:1.8; padding:10px 18px;">
	<table class="zimam-hdr" style="width:100%; border-bottom:2px solid #1B5E20; margin-bottom:12px;">
		<tr>
			<td style="width:36%; text-align:right; vertical-align:bottom; font-size:11pt; color:#444;">
				<div>رقم السند: <b><span dir="ltr" style="unicode-bidi:isolate;">{{ doc.name }}</span></b></div>
				<div>التاريخ: <b>{{ doc.zimam_date_hijri or hijri_str(doc.posting_date) }}</b> الموافق <span dir="ltr" style="unicode-bidi:isolate;">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</span>م</div>
				<div>الحالة: <b{% if doc.docstatus != 1 %} style="color:#C62828;"{% endif %}>{{ state }}</b></div>
			</td>
			<td style="width:30%; text-align:center; vertical-align:bottom; font-size:20pt; font-weight:bold; color:#1B5E20;">سند قبض</td>
			<td style="width:34%;"></td>
		</tr>
	</table>

	<p>استلمنا من <b>{{ doc.party_name or doc.party or "—" }}</b> مبلغًا وقدره <b>{{ money(doc.received_amount) }}</b> ({{ words(doc.received_amount) }})
	{% if doc.remarks %}وذلك عن: <b>{{ doc.remarks }}</b>{% endif %}.</p>

	<table style="width:100%; border-collapse:collapse; font-size:12pt; margin:8px 0;">
		<tr><td {{ lbl }}>طريقة القبض</td><td {{ td }}>{{ doc.mode_of_payment or "—" }}{% if doc.reference_no %} — <span dir="ltr" style="unicode-bidi:isolate;">{{ doc.reference_no }}</span>{% endif %}</td>
			<td {{ lbl }}>الصندوق / الحساب</td><td {{ td }}>{{ fund_name or acct(doc.paid_to) }}</td></tr>
		<tr><td {{ lbl }}>المشروع</td><td {{ td }}>{% if doc.project %}{{ frappe.db.get_value("Project", doc.project, "project_name") or doc.project }}{% else %}—{% endif %}</td>
			<td {{ lbl }}>{% if doc.reference_date %}تاريخ المرجع{% else %}الشركة{% endif %}</td><td {{ td }}>{% if doc.reference_date %}<span dir="ltr" style="unicode-bidi:isolate;">{{ frappe.format(doc.reference_date, {"fieldtype": "Date"}) }}</span>{% else %}{{ org_name }}{% endif %}</td></tr>
	</table>

	{% if doc.references %}
	<table style="width:100%; border-collapse:collapse; font-size:12pt; margin-top:6px;">
		<thead><tr style="background:#1B5E20; color:#fff;"><th {{ td }}>المستند المسدَّد</th><th {{ td }}>رقمه</th><th {{ td }}>المبلغ المخصَّص</th></tr></thead>
		<tbody>
		{% for r in doc.references %}
			<tr><td {{ td }}>{{ _(r.reference_doctype) }}</td><td {{ td }}><span dir="ltr" style="unicode-bidi:isolate;">{{ r.reference_name }}</span></td><td {{ td }}>{{ money(r.allocated_amount) }}</td></tr>
		{% endfor %}
		</tbody>
	</table>
	{% if doc.unallocated_amount %}<div style="font-size:11pt; color:#555; margin-top:4px;">دفعة غير مخصَّصة لمستند: {{ money(doc.unallocated_amount) }}</div>{% endif %}
	{% endif %}

	<table style="width:100%; margin-top:28px; font-size:11.5pt; text-align:center;">
		<tr>
			<td style="width:33%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">المحاسب<br><span style="color:#555; font-size:10pt;">{{ user(doc.owner) }}</span></div></td>
			<td style="width:33%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">أمين الصندوق<br><span style="color:#555; font-size:10pt;">الاسم والتوقيع</span></div></td>
			<td style="width:33%; vertical-align:top;"><div style="height:36px;"></div><div style="border-top:1px solid #999; padding-top:4px;">الدافع / المودِع<br><span style="color:#555; font-size:10pt;">الاسم والتوقيع</span></div></td>
		</tr>
	</table>
</div>
{%- if _lh and _lh.footer and "<!--zimam-->" in (_lh.content or "") -%}<div class="zimam-lh-foot" style="position:absolute; bottom:0; left:0; right:0; max-height:3.4cm; overflow:hidden;">{{ _lh.footer }}</div>{%- endif -%}
</div>
